(()=>{const r={sizes:[],data:[]};for(const pair of [[2,3],[0,0],[-1,2],[1.5,2],[NaN,2],[Infinity,2]])try{let c=new OffscreenCanvas(...pair);r.sizes.push([c.width,c.height])}catch(e){r.sizes.push(e.name)}const canvas=new OffscreenCanvas(2,3),ctx=canvas.getContext('2d');r.context={same:ctx===canvas.getContext('2d'),other:canvas.getContext('webgl'),alpha:ctx.getContextAttributes().alpha,tag:Object.prototype.toString.call(ctx)};ctx.fillStyle='red';ctx.scale(2,3);canvas.width=2;r.reset={fill:ctx.fillStyle,a:ctx.getTransform().a};const bitmap=canvas.transferToImageBitmap();r.bitmap={w:bitmap.width,h:bitmap.height};ctx.fillStyle='blue';const im=new ImageData(new Uint8ClampedArray([1,2,3,4,5,6,7,8]),2);ctx.putImageData(im,0,0);r.pixels=Array.from(ctx.getImageData(0,0,2,1).data);bitmap.close();r.closed=[bitmap.width,bitmap.height];for(const args of [[0,1],[2,0],[-2,3],[new Uint8ClampedArray(8),1],[new Uint8Array(8),1],[new Uint8ClampedArray(7),1]])try{let d=new ImageData(...args);r.data.push({width:d.width,height:d.height,space:d.colorSpace})}catch(e){r.data.push(e.name)}return r})()
